"""Middle of the Linked List — fast and slow pointers.

With an even count the fast pointer runs off the end one step later, which is
why `slow` lands on the second middle node.

Time: O(n)   Space: O(1)
"""
if "ListNode" not in globals():
    class ListNode:
        def __init__(self, val=0, next=None):
            self.val = val
            self.next = next


class Solution:
    def middleNode(self, head):
        slow = fast = head
        while fast and fast.next:
            slow = slow.next
            fast = fast.next.next
        return slow
